from pathlib import Path
import json
p=Path("BUUURT_Bibliotheque_Visuelle_20_Ecrans_Menu_NL.html")
s=p.read_text(encoding="utf-8")
a=s.index("const pages=")+len("const pages=")
b=s.index(";let selected=",a)
pages=json.loads(s[a:b])
screen=next(x for x in pages if x["en"]=="USR-LOC-002")
old='<div class="section"><h2>Autour de moi</h2><p>Aucune annonce disponible dans le rayon sélectionné.</p></div><a class="button" href="HAB-MAN-001.html">Choisir mes quartiers</a>'
assert screen["html"].count(old)==1,"Expected old message not found exactly once"
new='''<style>.arrival{padding:16px 19px 26px;flex:1;text-align:center}.arrival input[type=radio]{position:absolute;opacity:0}.arrival .langs{display:flex;justify-content:center;gap:8px;margin:0 0 18px}.arrival .langs label{border:1px solid #ddd;border-radius:20px;padding:7px 15px;font-size:12px;cursor:pointer}.arrival:has(#lfr:checked) label[for=lfr],.arrival:has(#lnl:checked) label[for=lnl],.arrival:has(#len:checked) label[for=len]{background:#ed0060;color:white;border-color:#ed0060}.arrival .copy{display:none}.arrival:has(#lfr:checked) .fr,.arrival:has(#lnl:checked) .nl,.arrival:has(#len:checked) .en{display:block}.arrival h2{font-size:21px;line-height:1.25}.arrival p{font-size:13px;line-height:1.5;color:#444}.arrival .cta{display:block;margin:14px 0 0;background:#ed0060;color:white;border-radius:12px;padding:13px 8px;font-size:13px;font-weight:bold;text-decoration:none}.arrival .email{width:100%;padding:12px;border:1px solid #ccc;border-radius:9px;margin-top:8px}.arrival .consent{display:flex;gap:7px;text-align:left;font-size:11px;color:#555;margin:12px 0}.arrival .hint{font-size:11px;color:#777}.arrival .request{border:1px solid #ed0060;border-radius:10px;padding:10px;margin-top:13px;font-size:12px;color:#555}</style><section class="arrival"><input id="lfr" type="radio" name="arrival-lang" checked><input id="lnl" type="radio" name="arrival-lang"><input id="len" type="radio" name="arrival-lang"><div class="langs"><label for="lfr">FR</label><label for="lnl">NL</label><label for="len">EN</label></div><div class="copy fr"><h2>BUUURT arrive bientôt dans votre quartier !</h2><p>Nous ne sommes pas encore présents dans votre secteur. Découvrez les quartiers disponibles ou laissez-nous votre adresse e-mail pour être informé de notre arrivée.</p><a class="cta" href="HAB-MAN-001.html">Voir les quartiers disponibles</a><div class="request">Prévenez-moi de l’arrivée de BUUURT<input class="email" type="email" placeholder="Votre adresse e-mail" aria-label="Adresse e-mail"><label class="consent"><input type="checkbox"> J’accepte de recevoir un e-mail lorsque BUUURT sera disponible dans mon quartier.</label><p class="hint">Maquette : envoi non activé</p></div></div><div class="copy nl"><h2>BUUURT komt binnenkort naar jouw buurt!</h2><p>We zijn nog niet actief in jouw buurt. Ontdek de buurten waar BUUURT al beschikbaar is of laat je e-mailadres achter om te horen wanneer we bij jou in de buurt starten.</p><a class="cta" href="HAB-MAN-001.html">Bekijk beschikbare buurten</a><div class="request">Houd me op de hoogte<input class="email" type="email" placeholder="Jouw e-mailadres" aria-label="E-mailadres"><label class="consent"><input type="checkbox"> Ik wil een e-mail ontvangen zodra BUUURT in mijn buurt beschikbaar is.</label><p class="hint">Prototype: verzenden nog niet beschikbaar</p></div></div><div class="copy en"><h2>BUUURT is coming to your neighborhood!</h2><p>We're not available in your area yet. Explore the neighborhoods where BUUURT is available, or leave your email address to hear when we arrive.</p><a class="cta" href="HAB-MAN-001.html">Explore available neighborhoods</a><div class="request">Notify me when BUUURT arrives<input class="email" type="email" placeholder="Your email address" aria-label="Email address"><label class="consent"><input type="checkbox"> I agree to receive an email when BUUURT becomes available in my neighborhood.</label><p class="hint">Prototype: sending not enabled</p></div></div></section>'''
screen["html"]=screen["html"].replace(old,new)
assert "buuurt-bottom-nav" in screen["html"]
assert len(pages)==20
out=s[:a]+json.dumps(pages,ensure_ascii=False)+s[b:]
assert "BUUURT arrive bientôt dans votre quartier !" in out
p.write_text(out,encoding="utf-8")
print("Validated 20 screens, updated USR-LOC-002")
